+/** Variance per item between two days (inclusive): theoretical use from sales vs actual consume movements. */
+export function varianceReport(store, from, to) {
+  const rows = new Map();
+  const row = (itemId) => {
+    if (!rows.has(itemId)) rows.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    return rows.get(itemId);
+  };
+  for (const sale of store.data.sales ?? []) {
+    const day = sale.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    for (const line of sale.lines) for (const u of line.uses) row(u.itemId).theoretical += u.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) row(batch.itemId).actual += m.qty;
+  }
+  const r3 = (n) => Math.round(n * 1000) / 1000;
+  return [...rows.values()]
+    .filter((x) => x.theoretical > 0 || x.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId)
+    .map((x) => ({
+      itemId: x.itemId,
+      name: store.data.items.find((i) => i.id === x.itemId)?.name ?? null,
+      theoretical: r3(x.theoretical),
+      actual: r3(x.actual),
+      difference: r3(x.actual - x.theoretical),
+    }));
+}
